effect.shader:
vec4 tex(vec2 p){ return texture2DCv(inputImg.texture, p); }
float bhash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
void main(){
vec2 uv = acScreenNorm;
vec2 st = 1.0 / max(acScreenSize, vec2(1.0));
float t = floor(acTime * speed);
vec2 cell = floor(uv * grid);
float n1 = bhash(cell + t * 1.7) - 0.5;
float n2 = bhash(cell + t * 1.7 + 19.19) - 0.5;
vec2 off = vec2(n1, n2) * amount * st;
vec2 u2 = clamp(uv + off * mixAmt, vec2(0.0), vec2(1.0));
vec4 c = tex(u2);
gl_FragColor = vec4(c.rgb, c.a);
}
